<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\SubscriptionEligibilityService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('SUBSCRIPTION_REVIEW_QUEUE_VIEW');$id=(int)($_GET['id']??0);$errors=[];$s=SubscriptionEligibilityService::operationsFind($id);if(!$s){http_response_code(404);exit('Subscription not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{SubscriptionEligibilityService::confirmPaymentAndActivate($id,(int)Auth::user()['id'],(string)$_POST['end_at'],(string)($_POST['payment_reference']??''),(string)($_POST['note']??''));header('Location: '.Url::to('operations/subscriptions.php?activated=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$pageTitle='Confirm Payment & Activate';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1><?=h($s['plan_name'])?></h1><p><?=h($s['owner_company_name']?:$s['owner_user_name'])?> · <?=h($s['subscription_ref'])?></p></div><span class="status-pill status-<?=h($s['subscription_state'])?>"><?=h($s['subscription_state'])?></span></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><div class="grid"><div class="card"><h3>Plan limits</h3><p>Trucks: <?=h($s['max_trucks']??'Unlimited')?></p><p>Drivers: <?=h($s['max_drivers']??'Unlimited')?></p></div><div class="card"><h3>Carrier compliance</h3><p>Verification: <?=h($s['carrier_verification'])?></p><p>Licence expiry: <?=h($s['business_license_expiry']?:'Missing')?></p><p>Insurance expiry: <?=h($s['insurance_expiry']?:'Missing')?></p></div><div class="card"><h3>Submitted payment details</h3><p>Reference: <strong><?=h($s['payment_reference']?:'Not submitted')?></strong></p><p><?=nl2br(h($s['activation_note']?:'No bank transfer details submitted yet.'))?></p></div></div><?php if($s['subscription_state']==='requested'&&Auth::can('SUBSCRIPTION_ACTIVATE')):?><form method="post" class="card" style="margin-top:18px"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><div class="notice">Confirm only after checking the submitted bank transfer. If another plan is currently active, this paid plan is automatically scheduled to start when the current plan ends.</div><div class="form-grid"><div class="field"><label>Payment reference</label><input type="text" name="payment_reference" required minlength="3" maxlength="96" pattern="[A-Za-z0-9._:/-]+" value="<?=h($s['payment_reference']?:'')?>" placeholder="Example: TXN-123456"></div><div class="field"><label>New plan end date/time</label><input type="datetime-local" name="end_at" required></div><div class="field full"><label>Operations confirmation note <span class="muted">(optional)</span></label><textarea name="note" maxlength="2000" rows="4"></textarea></div></div><button class="button" style="margin-top:12px">Confirm payment &amp; activate or schedule</button></form><?php endif;?><?php require BASE_PATH.'/app/Views/layout/footer.php';
